<template>
 <el-badge v-if="can('metal:warehouse-order:receive')||can('metal:warehouse-order:accept')||can('metal:storage-review:manage')" is-dot :hidden="count<=0" class="pending-review-badge"><el-button class="list-action list-action--primary list-action--row pending-review-trigger" @click="open">待复验消息<span v-if="count">（{{count}}）</span></el-button></el-badge>
 <el-drawer v-model="visible" title="待复验消息" class="pending-review-drawer" size="min(620px,94vw)" append-to-body>
  <FactoryToolbar/><el-select v-if="can('metal:storage-review:manage')" v-model="scope" @change="load"><el-option label="我的待复验" value="mine"/><el-option label="本厂待复验管理" value="manage"/></el-select>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button>
  <el-empty v-if="!rows.length&&!loading" :description="state.factoryId?'暂无待复验消息':'请先选择所属工厂'"/>
  <div v-loading="loading"><div v-for="row in rows" :key="row.id" class="review-message"><button @click="view(row)"><strong>{{receives(row.type||row.taskType)?'领料复验':'仓管复验'}}</strong><span>{{row.documentNumber||row.number}}</span><span>{{row.createTime||row.createdAt}}</span></button><el-button v-if="scope==='manage'&&can('metal:storage-review:manage')" :disabled="row.type==='PRODUCTION_OUT'" :title="row.type==='PRODUCTION_OUT'?'领料复验固定为本批加工人员；更换人员前须撤销领料单':''" @click="openAssign(row)">转派</el-button></div></div>
  <el-pagination v-model:current-page="page" :page-size="16" :total="total" layout="prev,pager,next" @current-change="load"/>
 </el-drawer>
 <el-dialog v-model="assignOpen" title="转派复验任务" width="480px" append-to-body :close-on-click-modal="false" :before-close="closeAssign"><OperationStatus :operation="operation"/><el-alert v-if="assignError" :title="assignError" type="error" :closable="false"/><el-form v-loading="assignLoading" label-position="top" :disabled="assignLoading||!!assignError||operation.busy.value||!!operation.pending.value"><el-form-item label="复验人员" required><el-select v-model="reviewerId" filterable><el-option v-for="p in eligibleReviewers" :key="p.id" :label="p.name||p.nickName" :value="p.id"/></el-select></el-form-item><el-form-item label="转派原因" required><el-input v-model="reason" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="closeAssign()">取消</el-button><el-button type="primary" :loading="operation.busy.value" :disabled="assignLoading||!!assignError||!!operation.pending.value||!reviewerId||!reason.trim()" @click="assign">确认转派</el-button></template></el-dialog>
<ReviewDialog ref="reviewDialog" @saved="load"/></template>
<script setup lang="ts">
import FactoryToolbar from '../storage-live/FactoryToolbar.vue'
import ReviewDialog from '../storage-live/ReviewDialog.vue'
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import request from '@/utils/request'
import {useStorage,useOperation,message,type Row} from '../storage-live/client';import OperationStatus from '../storage-live/OperationStatus.vue'
const reviewDialog=ref<InstanceType<typeof ReviewDialog>>();const {state,user,can,context}=useStorage(),router=useRouter(),visible=ref(false),count=ref(0),rows=ref<Row[]>([]),total=ref(0),page=ref(1),scope=ref('mine'),loading=ref(false),error=ref(''),assignOpen=ref(false),target=ref<Row>(),reviewerId=ref(''),reason=ref('')
let epoch=0,timer:ReturnType<typeof setInterval>|undefined,disposed=false
let assignEpoch=0
const assignLoading=ref(false),assignError=ref('')
const receives=(type:string)=>['RECEIVE','PRODUCTION_OUT','PRODUCT_OUT','SEMI_OUT','RAW_OUT'].includes(type)
const eligibleReviewers=computed<Row[]>(()=>target.value?.reviewers||[])
const operation=useOperation('/metal/storage-orders',context,async()=>{assignOpen.value=false;await load()})
async function load(){const id=++epoch,current=context();if(!state.factoryId||!(can('metal:warehouse-order:receive')||can('metal:warehouse-order:accept')||can('metal:storage-review:manage'))){count.value=0;rows.value=[];return}loading.value=true;error.value='';try{const c:any=await request({url:'/metal/storage-review-tasks/count',params:{factoryId:state.factoryId,scope:'mine'},quiet:true});if(disposed||id!==epoch||current!==context())return;count.value=Number(c.data?.count??c.data??0);if(visible.value){const r:any=await request({url:'/metal/storage-review-tasks/list',params:{factoryId:state.factoryId,scope:scope.value,pageNum:page.value,pageSize:16},quiet:true});if(disposed||id!==epoch||current!==context())return;rows.value=r.rows||r.data?.rows||r.data||[];total.value=r.total??r.data?.total??rows.value.length}}catch(e){if(current===context()&&id===epoch)error.value=message(e)}finally{if(id===epoch)loading.value=false}}
function open(){visible.value=true;page.value=1;void load()}
function view(row:Row){visible.value=false;void reviewDialog.value?.open(String(row.documentId),scope.value==='manage'?String(row.id):undefined)}
async function openAssign(row:Row){if(operation.busy.value||operation.pending.value||row.type==='PRODUCTION_OUT')return;const round=++assignEpoch,current=context();target.value=undefined;reviewerId.value='';reason.value='';assignError.value='';operation.clear();assignOpen.value=true;assignLoading.value=true;try{const response:any=await request({url:`/metal/storage-review-tasks/${row.id}`,params:{factoryId:state.factoryId},quiet:true});if(disposed||round!==assignEpoch||current!==context()||!assignOpen.value)return;const latest=response.data;if(!latest?.document||latest.document.status!=='PENDING_REVIEW')throw Error('任务已变化，请关闭后重新加载');if(latest.document.type==='PRODUCTION_OUT')throw Error('领料复验固定为本批加工人员，不能转派');target.value={...row,...latest}}catch(e){if(round===assignEpoch&&current===context())assignError.value=message(e)}finally{if(round===assignEpoch)assignLoading.value=false}}
function closeAssign(done?:()=>void){if(operation.busy.value||operation.pending.value)return;assignEpoch++;assignOpen.value=false;done?.()}
function assign(){if(!assignLoading.value&&!assignError.value&&target.value&&eligibleReviewers.value.some(p=>String(p.id)===String(reviewerId.value)))void operation.send(`/metal/storage-review-tasks/${target.value.id}/reassign`,{factoryId:state.factoryId,version:target.value.version,reviewRound:target.value.reviewRound,reviewerId:reviewerId.value,reason:reason.value.trim()})}
function refresh(){if(document.visibilityState==='visible'&&!operation.busy.value&&!operation.pending.value)void load()}
watch(()=>[state.factoryId,user.sessionEpoch,user.permissions.join('|')],()=>{epoch++;rows.value=[];count.value=0;assignOpen.value=false;refresh()})
onMounted(()=>{refresh();timer=setInterval(refresh,30000);document.addEventListener('visibilitychange',refresh);window.addEventListener('storage-documents-changed',refresh)})
onBeforeUnmount(()=>{disposed=true;epoch++;clearInterval(timer);document.removeEventListener('visibilitychange',refresh);window.removeEventListener('storage-documents-changed',refresh)})
</script>
<style scoped>.pending-review-trigger{white-space:nowrap}.review-message{display:flex;align-items:center;gap:10px;margin:12px 0;padding:14px;border:1px solid #e2e8f0;border-radius:6px}.review-message>button{border:0;background:transparent;display:flex;flex:1;min-width:0;flex-direction:column;gap:8px;text-align:left;cursor:pointer;overflow-wrap:anywhere}.review-message span{color:#909399;font-size:13px}</style>
